function DirectionArt({category,small=false}:{category:Category;small?:boolean}){
 if(category.id==='restaurante')return <div className={'ss-restaurant-direction '+(small?'small':'')} aria-hidden="true"><div className="ss-rd-brand">LASTRO<span>COZINHA DE MAR E FOGO</span></div><div className="ss-rd-story">O mar decide.<em>A brasa transforma.</em></div><img src={restaurantPhoto} alt=""/><div className="ss-rd-menu">HOJE, NA BRASA<b>Peixe do dia</b><b>Abóbora</b><b>Cocada de forno</b></div><div className="ss-rd-bottom">A mesa é parte da cozinha.</div></div>;
 return <div className={`ss-direction-art ${category.id} ${small?'small':''}`} style={{'--direction':category.color} as React.CSSProperties} aria-hidden="true"><div className="ss-mini-nav"><b>{category.demo_name}</b><span>Conheça · Contato ↗</span></div><div className="ss-mini-copy"><span>{category.sector.toUpperCase()}</span><h3>{category.headline}</h3><i>Explore a experiência ↗</i></div><div className="ss-mini-scene"><div className="ss-art-sun"/><div className="ss-art-building"><i/><i/><i/><i/></div><div className="ss-art-pool"/><div className="ss-art-leaf"/><div className="ss-art-detail"/></div><div className="ss-mini-bottom"><span>01 / ESSÊNCIA</span><b>{category.description}</b></div></div>;
}
function CheckList({items}:{items?:CheckItem[]}){return <div className="ss-checks">{items?.map((c,i)=><details key={c.name+i} className={c.status}><summary>{c.status==='passed'?<Check size={14}/>:c.status==='failed'?<X size={14}/>:<Clock size={14}/>}<span>{c.name}</span><small>{c.status==='passed'?'PASSOU':c.status==='failed'?'FALHOU':'NÃO EXECUTADO'}</small></summary><p>{c.detail}</p></details>)}</div>;}

