 useEffect(()=>{if(project?.status!=='running')return;const timer=setInterval(()=>{setNow(Date.now());if(document.hidden)return;void jsonApi('/studio/projects/'+project.id).then(data=>{if(!alive.current)return;setProject(data);if(data.status!=='running'){if(['ready','ideas_ready'].includes(data.status)&&['site','directions'].includes(data.job_kind))setPrompt('');void refreshProjects();if(data.status==='ideas_ready'&&data.job_kind==='directions')setTab('ideas');if(data.status==='ready'&&announced.current!==data.id+data.revision){announced.current=data.id+data.revision;sayRef.current('Senhor, a nova versão está salva. Abra a prévia e confira os testes antes de aprovar.');}}}).catch(fail);},1500);return()=>clearInterval(timer);},[project?.id,project?.status,refreshProjects]);
