   try{const result=await jsonApi('/studio/projects/'+p!.id+'/'+(kind==='directions'?'directions':'generate'),{mode,prompt:brief.trim()||prompt,provider,reference,reference_asset:referenceAsset,research_images:researchImages});setCurrent(result);setTab(kind==='directions'?'ideas':'preview');setWizard(false);}catch(e){setCurrent(p!);setMode(mode);setPrompt(brief);throw e;}finally{void refreshProjects();}
